import ctypes
import ctypes.util

libcrypto_path = ctypes.util.find_library('crypto')
if libcrypto_path:
    libcrypto = ctypes.CDLL(libcrypto_path)
    libcrypto.SHA256.argtypes = [ctypes.c_char_p, ctypes.c_size_t, ctypes.c_char_p]
